                </div>
                <div className="flex items-center space-x-2">
                  <button className="px-4 py-2 border border-slate-300 rounded-lg font-semibold hover:bg-slate-50">
                    Filter
                  </button>
                  <button className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-lg">
                    Applied (3)
                  </button>
                </div>
              </div>

              <div className="space-y-4">
                {placements.map((placement, idx) => (
                  <div
                    key={idx}
                    className="border-2 border-slate-200 rounded-xl p-6 hover:border-blue-500 hover:shadow-lg transition-all"
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex items-start space-x-4 flex-1">
                        <div className="text-4xl">{placement.logo}</div>
                        <div className="flex-1">
                          <div className="flex items-center space-x-3 mb-2">
                            <h3 className="text-xl font-bold text-slate-900">{placement.company}</h3>
                            <span className={`px-3 py-1 rounded-full text-xs font-semibold ${
                              placement.status === 'Open' 
                                ? 'bg-green-100 text-green-700' 
                                : 'bg-orange-100 text-orange-700'
                            }`}>
                              {placement.status}
                            </span>
                            <span className={`px-3 py-1 rounded-full text-xs font-semibold ${
                              placement.type === 'Full-time' 
                                ? 'bg-blue-100 text-blue-700' 
                                : 'bg-purple-100 text-purple-700'
                            }`}>
                              {placement.type}
                            </span>
                          </div>
                          <p className="text-lg font-semibold text-blue-600 mb-2">{placement.role}</p>
                          <div className="flex items-center space-x-6 text-sm text-slate-600">
                            <span className="flex items-center space-x-1">
                              <TrendingUp className="h-4 w-4" />
                              <span className="font-semibold">{placement.package}</span>
                            </span>
                            <span className="flex items-center space-x-1">
                              <Clock className="h-4 w-4" />
                              <span>Deadline: {placement.deadline}</span>
                            </span>
                          </div>
                        </div>
                      </div>
                      <button className="px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-xl transition-all shadow-lg hover:shadow-xl">
                        Apply Now
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Events & Workshops Tab */}
        {activeTab === 'events' && (
          <div className="space-y-6">
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6">
              <div className="flex items-center justify-between mb-6">
                <div className="flex items-center space-x-3">
                  <CalendarDays className="h-6 w-6 text-emerald-600" />
                  <h2 className="text-2xl font-bold text-slate-900">College Events & Workshops</h2>
                </div>
                <button className="px-4 py-2 border border-slate-300 rounded-lg font-semibold hover:bg-slate-50">
                  View Calendar
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {collegeEvents.map((event, idx) => (
                  <div
                    key={idx}
                    className="border-2 border-slate-200 rounded-xl p-6 hover:border-emerald-500 hover:shadow-lg transition-all"
                  >
                    <div className="flex items-start justify-between mb-4">
                      <h3 className="text-xl font-bold text-slate-900">{event.title}</h3>
                      <span className={`px-3 py-1 rounded-full text-xs font-semibold ${eventTypeColors[event.type.toLowerCase()] || 'bg-gray-100 text-gray-700'}`}>
                        {event.type}
                      </span>
                    </div>

                    <p className="text-sm text-slate-600 mb-4">{event.description}</p>

                    <div className="space-y-2 text-sm text-slate-600">
                      <div className="flex items-center space-x-2">
                        <CalendarDays className="h-4 w-4 text-emerald-600" />
                        <span className="font-semibold">{event.date}</span>
                      </div>
                      <div className="flex items-center space-x-2">
                        <User className="h-4 w-4 text-emerald-600" />
                        <span>{event.venue}</span>
                      </div>
                    </div>

                    <button className="w-full mt-4 px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-lg transition-all">
                      Register Now
                    </button>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default StudentDashboard;
